<?php $activeMenu='router';$routerView='firewall';require_once __DIR__.'/../includes/sidebar.php'; ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Firewall - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css"><link rel="stylesheet" href="../assets/css/common.css"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><style>body{margin:0}.page{margin-left:220px;padding:32px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.title{font-size:28px;font-weight:700}.sub,.muted{color:#66758d}.btn{border:1px solid #d7e0ec;background:#fff;border-radius:8px;padding:10px 14px;font-weight:600;cursor:pointer}.primary{background:#087cff;color:#fff;border-color:#087cff}.tabs{display:flex;gap:8px;padding:15px 20px;border-bottom:1px solid #e4e9f0}.tab{cursor:pointer;border:1px solid #dce4ef;background:#fff;border-radius:8px;padding:8px 13px;font-weight:600}.tab.active{background:#087cff;color:#fff;border-color:#087cff}.card{background:#fff;border:1px solid #dce4ef;border-radius:14px;overflow:hidden}.bar{padding:16px 20px;display:flex;justify-content:space-between}.wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px 14px;border-bottom:1px solid #edf1f6;text-align:left;font-size:12px}th{font-size:10px;text-transform:uppercase;color:#61718a;background:#f7f9fc}.badge{padding:5px 8px;border-radius:99px;font-size:10px;font-weight:700}.on{background:#dff6e9;color:#08774e}.off{background:#fde5e5;color:#b42318}.notice{padding:18px;color:#66758d}@media(max-width:800px){.page{margin-left:0;padding:20px}.head{align-items:flex-start;flex-direction:column;gap:12px}}</style></head><body><main class="page"><div class="head"><div><div class="title">Firewall</div><div class="sub">Filter, NAT, dan Mangle RouterOS dalam mode monitoring.</div></div><button class="btn primary" id="refresh">↻ Refresh</button></div><div class="card"><div class="tabs"><button class="tab active" data-kind="filter">Filter Rules</button><button class="tab" data-kind="nat">NAT</button><button class="tab" data-kind="mangle">Mangle</button></div><div class="bar"><strong id="router">Router</strong><span class="muted" id="updated">Belum diperbarui</span></div><div class="wrap"><table><thead><tr><th>Chain</th><th>Action</th><th>Protocol</th><th>Source</th><th>Destination</th><th>Interface</th><th>Packets</th><th>Bytes</th><th>Status</th></tr></thead><tbody id="rows"><tr><td colspan="9" class="notice">Memuat firewall...</td></tr></tbody></table></div></div></main><script>const rows=document.getElementById('rows'),router=document.getElementById('router'),updated=document.getElementById('updated'),refresh=document.getElementById('refresh');let data={},kind='filter';const esc=v=>String(v??'-').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));function render(){const a=data[kind]||[];rows.innerHTML=a.map(x=>`<tr><td>${esc(x.chain)}</td><td><b>${esc(x.action)}</b></td><td>${esc(x.protocol||'all')}</td><td>${esc(x.src||'any')}</td><td>${esc(x.dst||'any')}</td><td>${esc(x.in_interface||x.out_interface||'any')}</td><td>${esc(x.packets)}</td><td>${esc(x.bytes)}</td><td><span class="badge ${x.disabled?'off':'on'}">${x.disabled?'DISABLED':'ENABLED'}</span></td></tr>`).join('')||'<tr><td colspan="9" class="notice">Tidak ada rule.</td></tr>'}async function load(){refresh.disabled=true;try{const r=await fetch('../api/router_firewall.php?nocache='+Date.now(),{cache:'no-store'}),d=await r.json();if(d.status!=='online')throw Error(d.message||'Router offline');data=d;router.textContent=d.router||'Router';render()}catch(e){rows.innerHTML='<tr><td colspan="9" class="notice">Gagal mengambil data: '+esc(e.message)+'</td></tr>'}finally{updated.textContent='Update '+new Date().toLocaleTimeString('id-ID');refresh.disabled=false}}document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');kind=b.dataset.kind;render()});refresh.onclick=load;load();setInterval(load,10000);</script><script src="../assets/js/app.js?v=6"></script></body></html>